import { createReadStream } from 'node:fs';
import { mkdir, rename, rm, stat, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { randomBytes } from 'node:crypto';
import type { Readable } from 'node:stream';

/**
 * Blob storage for uploaded images (§2, §4.5). Keys are generated by the server only:
 * `<householdId>/<imageId>-<variant>.webp`. Every key is validated strictly so that no
 * caller can ever escape the storage root, even by mistake.
 */
export interface Storage {
  put(key: string, data: Buffer): Promise<void>;
  /** Readable stream of the object, or `null` when it does not exist. */
  getStream(key: string): Promise<Readable | null>;
  exists(key: string): Promise<boolean>;
  /** Deletes the object; missing objects are ignored. */
  delete(key: string): Promise<void>;
  /** Deletes every object below `prefix` (a single key segment, e.g. a household id). */
  deletePrefix(prefix: string): Promise<void>;
}

export class StorageKeyError extends Error {
  constructor(key: string) {
    super(`Invalid storage key: ${JSON.stringify(key)}`);
    this.name = 'StorageKeyError';
  }
}

const SEGMENT = /^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$/;
const FILE_SEGMENT = /^[A-Za-z0-9][A-Za-z0-9_-]{0,99}(\.[a-z0-9]{1,10})?$/;
/** Windows device names – irrelevant on Linux, rejected anyway so dev machines behave identically. */
const RESERVED_SEGMENT = /^(con|prn|aux|nul|com\d|lpt\d)(\.|$)/i;
const MAX_KEY_LENGTH = 255;
const MAX_DEPTH = 4;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * True for keys made of 1–4 `/`-separated segments of `[A-Za-z0-9_-]` where only the last segment
 * may carry a single lowercase extension. Rejects `..`, absolute paths, backslashes, drive letters,
 * empty segments, NUL bytes and anything non-ASCII.
 */
export function isValidStorageKey(key: unknown): key is string {
  if (typeof key !== 'string' || key.length === 0 || key.length > MAX_KEY_LENGTH) return false;
  const segments = key.split('/');
  if (segments.length > MAX_DEPTH) return false;
  return segments.every(
    (segment, index) =>
      !RESERVED_SEGMENT.test(segment) &&
      (index === segments.length - 1 ? FILE_SEGMENT.test(segment) : SEGMENT.test(segment)),
  );
}

export function assertValidStorageKey(key: string): void {
  if (!isValidStorageKey(key)) throw new StorageKeyError(key);
}

export type ImageVariantName = 'thumb' | 'full';

/** `<householdId>/<imageId>` – the prefix stored in `InventoryImage.storageKey`. */
export function imageStoragePrefix(householdId: string, imageId: string): string {
  if (!UUID.test(householdId) || !UUID.test(imageId)) {
    throw new StorageKeyError(`${householdId}/${imageId}`);
  }
  return `${householdId.toLowerCase()}/${imageId.toLowerCase()}`;
}

/** Full key of one image variant: `<householdId>/<imageId>-<variant>.webp`. */
export function imageVariantKey(storagePrefix: string, variant: ImageVariantName): string {
  const key = `${storagePrefix}-${variant}.webp`;
  assertValidStorageKey(key);
  return key;
}

/** Local filesystem implementation rooted at `rootDir` (`UPLOAD_DIR`). */
export class LocalStorage implements Storage {
  readonly rootDir: string;

  constructor(rootDir: string) {
    this.rootDir = path.resolve(rootDir);
  }

  /** Maps a validated key to an absolute path and double-checks containment. */
  resolveKey(key: string): string {
    assertValidStorageKey(key);
    const resolved = path.resolve(this.rootDir, ...key.split('/'));
    const relative = path.relative(this.rootDir, resolved);
    if (relative.length === 0 || relative.startsWith('..') || path.isAbsolute(relative)) {
      throw new StorageKeyError(key);
    }
    return resolved;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const target = this.resolveKey(key);
    await mkdir(path.dirname(target), { recursive: true });
    // Write to a temp file in the same directory, then rename atomically.
    const temp = `${target}.${randomBytes(6).toString('hex')}.tmp`;
    try {
      await writeFile(temp, data, { flag: 'wx' });
      await rename(temp, target);
    } catch (error) {
      await unlink(temp).catch(() => undefined);
      throw error;
    }
  }

  async getStream(key: string): Promise<Readable | null> {
    const target = this.resolveKey(key);
    try {
      const info = await stat(target);
      if (!info.isFile()) return null;
    } catch (error) {
      if (isNotFound(error)) return null;
      throw error;
    }
    return createReadStream(target);
  }

  async exists(key: string): Promise<boolean> {
    try {
      return (await stat(this.resolveKey(key))).isFile();
    } catch (error) {
      if (isNotFound(error)) return false;
      throw error;
    }
  }

  async delete(key: string): Promise<void> {
    try {
      await unlink(this.resolveKey(key));
    } catch (error) {
      if (!isNotFound(error)) throw error;
    }
  }

  async deletePrefix(prefix: string): Promise<void> {
    if (!SEGMENT.test(prefix)) throw new StorageKeyError(prefix);
    await rm(this.resolveKey(prefix), { recursive: true, force: true });
  }
}

function isNotFound(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    (error.code === 'ENOENT' || error.code === 'ENOTDIR')
  );
}
